"use client";

import type { IconifyIcon } from "@iconify/react";
import type { CSSProperties } from "react";

import { cn } from "@/lib/utils";
import type { IconValue } from "@/registry/new-york/picked-icon/icon-types";
import { IconGlyph } from "@/registry/new-york/picked-icon/IconGlyph";

export interface PickedIconProps {
  value: IconValue;
  size?: number;
  label?: string | undefined;
  className?: string;
  /** Supply preloaded SVG data for SSR or offline rendering. No API request is made. */
  iconData?: IconifyIcon;
}
const frames = { circle: "50%", rounded: "22%", square: "0", squircle: "50%" };
export const PickedIcon = ({
  value,
  size = 36,
  label,
  className,
  iconData,
}: PickedIconProps) => {
  const style: CSSProperties = {
    backgroundColor: value.background,
    borderRadius: frames[value.frame ?? "rounded"],
    color: value.color ?? "currentColor",
    height: size,
    width: size,
  };
  return (
    <span
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      className={cn(
        "inline-flex shrink-0 items-center justify-center align-middle",
        value.frame === "squircle" && "[corner-shape:squircle]",
        className
      )}
      style={style}
    >
      <span className="flex size-[60%] items-center justify-center">
        <IconGlyph name={value.name} data={iconData} />
      </span>
    </span>
  );
};

"use client";

import { Icon, loadIcon } from "@iconify/react";
import type { IconifyIcon } from "@iconify/react";
import { useEffect, useState } from "react";

export const IconGlyph = ({
  name,
  data,
}: {
  name: string;
  data?: IconifyIcon | undefined;
}) => {
  const [loaded, setLoaded] = useState<{
    name: string;
    data: IconifyIcon | null;
  }>();
  useEffect(() => {
    if (data) {
      return;
    }
    let active = true;
    const load = async () => {
      try {
        const icon = await loadIcon(name);
        if (active) {
          setLoaded({ data: icon, name });
        }
      } catch {
        if (active) {
          setLoaded({ data: null, name });
        }
      }
    };
    void load();
    return () => {
      active = false;
    };
  }, [name, data]);
  const icon = data ?? (loaded?.name === name ? loaded.data : undefined);
  if (icon === null) {
    return (
      <span title="Icon unavailable" aria-hidden="true">
        ?
      </span>
    );
  }
  if (!icon) {
    return (
      <span
        className="size-3 rounded-full bg-current opacity-20"
        aria-hidden="true"
      />
    );
  }
  return <Icon ssr icon={icon} width="100%" height="100%" aria-hidden="true" />;
};

